window.EW=window.EW||{pages:{}};window.EW.pages["wiki-herbier--plantes-innofensives"]={"html":"<div class=\"tbl-wrap\"><table class=\"doc-table\"><thead><tr><th scope=\"col\">Plante<\/th><th scope=\"col\">Description<\/th><\/tr><\/thead><tbody><tr><td><a href=\"#/p/wiki-herbier--plantes-innofensives--algue-commune\">Algue commune<\/a><\/td><td>Varech dont la gelée claire fait tenir un onguent là où on le pose.<\/td><\/tr><tr><td><a href=\"#/p/wiki-herbier--plantes-innofensives--armoise-lunaire\">Armoise lunaire<\/a><\/td><td>Armoise qui ouvre les autres plantes, et dont la force, chez les pieds résonants, suit la lune.<\/td><\/tr><tr><td><a href=\"#/p/wiki-herbier--plantes-innofensives--bonne-haleine-des-landes\">Bonne-haleine des landes<\/a><\/td><td>Petite plante dont le feuillage se referme en quelques secondes dès que l'air devient mauvais.<\/td><\/tr><tr><td><a href=\"#/p/wiki-herbier--plantes-innofensives--braisiere-des-coteaux\">Braisière des coteaux<\/a><\/td><td>Arbuste dont le bois brûle sans flamme ni fumée, à une chaleur toujours égale.<\/td><\/tr><tr><td><a href=\"#/p/wiki-herbier--plantes-innofensives--cactus-tonneau-des-serres\">Cactus-tonneau des serres<\/a><\/td><td>Cactus des pays secs dont les pieds, en terre résonante, tirent de l'eau de l'air nuit après nuit.<\/td><\/tr><tr><td><a href=\"#/p/wiki-herbier--plantes-innofensives--champignon-brun\">Champignon brun<\/a><\/td><td>Champignon ordinaire des caves, qui, séché en poudre, boit les liquides et les rend intacts.<\/td><\/tr><tr><td><a href=\"#/p/wiki-herbier--plantes-innofensives--champignon-phosphorescent\">Champignon phosphorescent<\/a><\/td><td>Champignon qui éclaire faiblement, sans flamme, sans chaleur et sans consommer l'air.<\/td><\/tr><tr><td>Dame de l'heure<\/td><td>Liliacée dont les douze fleurs s'ouvrent une par heure, toujours dans le même ordre.<\/td><\/tr><tr><td><a href=\"#/p/wiki-herbier--plantes-innofensives--delieuse-des-rocailles\">Délieuse des rocailles<\/a><\/td><td>Plante dont le liquide clair dissout à froid les résines, les gommes et les cires.<\/td><\/tr><tr><td><a href=\"#/p/wiki-herbier--plantes-innofensives--dictame-de-crete\">Dictame de Crète<\/a><\/td><td>Plante qui ôte la douleur d'une plaie pendant quelques heures, à l'endroit où on l'applique.<\/td><\/tr><tr><td><a href=\"#/p/wiki-herbier--plantes-innofensives--gourde-doffice\">Gourde d'office<\/a><\/td><td>Cucurbitacée dont le fruit sec sert de récipient, que rien de connu n'attaque ni ne traverse.<\/td><\/tr><tr><td><a href=\"#/p/wiki-herbier--plantes-innofensives--menthe-poivree\">Menthe poivrée<\/a><\/td><td>Menthe qui calme l'estomac sans rien masquer, ajoutée pour que le malade garde ce qu'on lui donne.<\/td><\/tr><tr><td><a href=\"#/p/wiki-herbier--plantes-innofensives--obligeante-des-haies\">Obligeante des haies<\/a><\/td><td>Plante de haies dont la feuille écrasée referme une plaie en quelques minutes, si une autre main l'applique.<\/td><\/tr><tr><td><a href=\"#/p/wiki-herbier--plantes-innofensives--patiente-des-murs\">Patiente des murs<\/a><\/td><td>Plante des maçonneries anciennes, connue pour ses propriétés de suspension.<\/td><\/tr><tr><td><a href=\"#/p/wiki-herbier--plantes-innofensives--peseuse-commune\">Peseuse commune<\/a><\/td><td>Légumineuse dont toutes les graines pèsent exactement le même poids, base du grain des apothicaires.<\/td><\/tr><tr><td><a href=\"#/p/wiki-herbier--plantes-innofensives--pleurote-des-ombres\">Pleurote des ombres<\/a><\/td><td>Champignon qui retire l'amertume d'une préparation en une nuit, à condition de l'ôter à l'heure.<\/td><\/tr><tr><td><a href=\"#/p/wiki-herbier--plantes-innofensives--prenante-des-rives\">Prenante des rives<\/a><\/td><td>Plante sans effet par elle-même, pourtant la plus employée des officines.<\/td><\/tr><\/tbody><\/table><\/div>","toc":[]};
